<template>
  <div>
    <p v-if="loading">Loading agreement…</p><p v-else-if="error" class="error">{{ error }}</p>
    <template v-else>
      <RouterLink :to="`/organizations/${agreement.organization}`">← Back to Organization</RouterLink>
      <div class="page-heading"><h1>{{ agreement.title }}</h1><p>{{ typeLabel }} · <span class="status-badge">{{ statusLabel }}</span></p></div>
      <div class="detail-card agreement-meta"><p><strong>Organization:</strong> {{ organizationName }}</p><p><strong>Signed date:</strong> {{ agreement.signed_date || '—' }}</p><p><strong>Start date:</strong> {{ agreement.start_date || '—' }}</p><p><strong>Expiration date:</strong> {{ agreement.expiration_date || '—' }}</p></div>
      <h2>Overview</h2><div class="detail-card">{{ agreement.description || 'No description recorded.' }}</div>
      <section><div class="section-heading"><h2>Contacts</h2><button class="primary small-button" @click="contactForm = !contactForm">+ Add Contact</button></div><form v-if="contactForm" class="detail-card simple-form" @submit.prevent="createContact"><label>Side<select v-model="contact.side"><option value="OUR_SIDE">Our side</option><option value="PARTNER_SIDE">Partner side</option></select></label><label>Full name<input v-model="contact.full_name" required></label><label>Position<input v-model="contact.position"></label><label>Email<input v-model="contact.email" type="email"></label><label>Phone<input v-model="contact.phone"></label><label>Role<input v-model="contact.role"></label><label class="checkbox"><input v-model="contact.is_primary" type="checkbox"> Primary</label><div><button class="primary" :disabled="saving">{{ saving ? 'Saving…' : 'Save Contact' }}</button><p v-if="formError" class="error">{{ formError }}</p></div></form><div v-if="contacts.length" class="contact-groups"><div v-for="group in contactGroups" :key="group.label"><h3>{{ group.label }}</h3><div v-if="group.items.length" class="detail-card contact-list"><div v-for="item in group.items" :key="item.id" class="contact-row"><strong>{{ item.contact_name }}</strong><span>{{ item.contact_position || '—' }}</span><span>{{ item.contact_email || '—' }}</span><span>{{ item.contact_phone || '—' }}</span><span>{{ item.role || '—' }}<small v-if="item.is_primary"> · Primary</small></span></div></div><p v-else class="empty">No contacts recorded.</p></div></div><p v-else class="empty">No contacts recorded.</p></section>
      <section><div class="section-heading"><h2>Documents</h2><button class="primary small-button" @click="documentForm = !documentForm">+ Upload Document</button></div><form v-if="documentForm" class="detail-card simple-form" @submit.prevent="uploadDocument"><label>Title<input v-model="document.title" required></label><label>Document type<input v-model="document.document_type"></label><label>File<input type="file" required @change="document.file = $event.target.files[0]"></label><label>Description<textarea v-model="document.description"></textarea></label><div><button class="primary" :disabled="saving">{{ saving ? 'Uploading…' : 'Upload Document' }}</button><p v-if="formError" class="error">{{ formError }}</p></div></form><div v-if="documents.length" class="detail-card"><div v-for="item in documents" :key="item.id" class="list-row"><strong>{{ item.title }}</strong><span>{{ item.document_type || '—' }}</span><span>{{ formatDate(item.uploaded_at) }}</span><a :href="item.file" target="_blank" rel="noopener">Open file</a></div></div><p v-else class="empty">No documents recorded.</p></section>
      <section><div class="section-heading"><h2>Activities</h2><button class="primary small-button" @click="activityForm = !activityForm">+ Add Activity</button></div><form v-if="activityForm" class="detail-card simple-form" @submit.prevent="createActivity"><label>Activity type<select v-model="activity.activity_type"><option v-for="(label, value) in ACTIVITY_TYPE_LABELS" :key="value" :value="value">{{ label }}</option></select></label><label>Title<input v-model="activity.title"></label><label>Date<input v-model="activity.activity_date" type="datetime-local" required></label><label>Description<textarea v-model="activity.description"></textarea></label><div><button class="primary" :disabled="saving">{{ saving ? 'Saving…' : 'Save Activity' }}</button><p v-if="formError" class="error">{{ formError }}</p></div></form><div v-if="activities.length" class="detail-card"><div v-for="item in sortedActivities" :key="item.id" class="list-row activity"><strong>{{ formatDate(item.activity_date) }}</strong><span>{{ activityType(item.activity_type) }}</span><span>{{ item.title || '—' }}</span><p v-if="item.description">{{ item.description }}</p></div></div><p v-else class="empty">No activities recorded.</p></section>
    </template>
  </div>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue'; import { useRoute } from 'vue-router'; import client from '../api/client'; import { AGREEMENT_TYPE_LABELS, AGREEMENT_STATUS_LABELS, ACTIVITY_TYPE_LABELS } from '../constants/partnerships'
const route=useRoute(), agreement=ref(null), contacts=ref([]), documents=ref([]), activities=ref([]), loading=ref(true), error=ref(''), saving=ref(false), formError=ref(''), contactForm=ref(false), documentForm=ref(false), activityForm=ref(false); const blankContact=()=>({side:'OUR_SIDE',full_name:'',position:'',email:'',phone:'',role:'',is_primary:false}), blankDocument=()=>({title:'',document_type:'',file:null,description:''}), blankActivity=()=>({activity_type:'NOTE',title:'',activity_date:'',description:''}); const contact=ref(blankContact()), document=ref(blankDocument()), activity=ref(blankActivity()); const typeLabel=computed(()=>AGREEMENT_TYPE_LABELS[agreement.value?.agreement_type]||agreement.value?.agreement_type), statusLabel=computed(()=>AGREEMENT_STATUS_LABELS[agreement.value?.status]||agreement.value?.status), organizationName=computed(()=>agreement.value?.organization_name||agreement.value?.organization), contactGroups=computed(()=>[{label:'Our side',items:contacts.value.filter(c=>c.side==='OUR_SIDE')},{label:'Partner side',items:contacts.value.filter(c=>c.side==='PARTNER_SIDE')}]), sortedActivities=computed(()=>[...activities.value].sort((a,b)=>new Date(b.activity_date)-new Date(a.activity_date))); const formatDate=v=>v?new Date(v).toLocaleString():'—'; const activityType=v=>ACTIVITY_TYPE_LABELS[v]||v; const list=r=>Array.isArray(r.data)?r.data:r.data.results||[]; const denied=e=>e.response?.status===403?'You do not have permission to perform this action.':(e.response?.data?.detail||'Unable to save.');
async function loadContacts(){contacts.value=list(await client.get('/api/agreement-contacts/',{params:{agreement:route.params.id}}))}; async function loadDocuments(){documents.value=list(await client.get('/api/documents/',{params:{agreement:route.params.id}}))}; async function loadActivities(){activities.value=list(await client.get('/api/activities/',{params:{agreement:route.params.id}}))}; async function write(fn){saving.value=true;formError.value='';try{await fn();formError.value=''}catch(e){formError.value=denied(e)}finally{saving.value=false}}; async function createContact(){await write(async()=>{const c=await client.post('/api/contacts/',{full_name:contact.value.full_name,position:contact.value.position,email:contact.value.email,phone:contact.value.phone});try{await client.post('/api/agreement-contacts/',{agreement:route.params.id,contact:c.data.id,side:contact.value.side,role:contact.value.role,is_primary:contact.value.is_primary})}catch(e){throw new Error('Contact was created, but linking it to this agreement failed. Please contact support.')} contact.value=blankContact();contactForm.value=false;await loadContacts()})}; async function uploadDocument(){await write(async()=>{const data=new FormData();Object.entries(document.value).forEach(([k,v])=>{if(v!==null)data.append(k,v)});data.append('agreement',route.params.id);await client.post('/api/documents/',data);document.value=blankDocument();documentForm.value=false;await loadDocuments()})}; async function createActivity(){await write(async()=>{await client.post('/api/activities/',{...activity.value,agreement:route.params.id});activity.value=blankActivity();activityForm.value=false;await loadActivities()})}
onMounted(async()=>{try{const id=route.params.id;const r=await Promise.all([client.get(`/api/agreements/${id}/`),loadContacts(),loadDocuments(),loadActivities()]);agreement.value=r[0].data}catch(e){error.value=e.response?.status===404?'Agreement not found.':'Unable to load agreement.'}finally{loading.value=false}})
</script>
